.new(0, 1),","                    NumberSequenceKeypoint.new(1, 0)","                }","                })","                ","                Items[\"PaletteDragger\"] = Library:Create(\"Frame\", {","                    Name = \"\\0\",","                    Parent = Items[\"Palette\"].Instance,","                    Size = UDim2.new(0, 1, 0, 1),","                    BackgroundColor3 = Color3.fromRGB(255, 255, 255),","                    BorderSizePixel = 0","                })","                ","                Library:Create(\"UIStroke\", {","                    Name = \"\\0\",","                    Parent = Items[\"PaletteDragger\"].Instance,","                    ApplyStrokeMode = Enum.ApplyStrokeMode.Border,","                    LineJoinMode = Enum.LineJoinMode.Miter,","                    Color = Library.Theme[\"Border\"]","                }):AddToTheme({Color = 'Border'})                ","","                Colorpicker.Items = Items","            end","","            function Colorpicker:SetVisibility(Bool)","                Items[\"ColorpickerButton\"].Instance.Visible = Bool","            end","","            function Colorpicker:Update(IsFromAlpha)","                local Hue, Saturation, Value = Colorpicker.Hue, Colorpicker.Saturation, Colorpicker.Value","                Colorpicker.Color = Color3.fromHSV(Hue, Saturation, Value)","                Colorpicker.HexValue = Colorpicker.Color:ToHex()","        ","                Items[\"ColorpickerButton\"]:Tween({BackgroundColor3 = Colorpicker.Color})","                Items[\"Palette\"]:Tween({BackgroundColor3 = Color3.fromHSV(Hue, 1, 1)})","","                Flags[Colorpicker.Flag] = {","                    Alpha = Colorpicker.Alpha,","                    Color = Colorpicker.Color,","                    HexValue = Colorpicker.HexValue,","                    Flag = Colorpicker.Flag,","                    Transparency = 1 - Colorpicker.Alpha","                }","","                Items[\"CurrentColor\"]:Tween({BackgroundColor3 = Colorpicker.Color})","    ","                if not IsFromAlpha then ","                    Items[\"Alpha\"]:Tween({BackgroundColor3 = Colorpicker.Color})","                end","    ","                if Data.Callback then ","                    Library:SafeCall(Data.Callback, Colorpicker.Color, Colorpicker.Alpha)","                end","            end","","            local Debounce = false ","            local ColorpickerWindow = Items[\"ColorpickerWindow\"].Instance","            local ColorpickerButton = Items[\"ColorpickerButton\"].Instance","","            local IsSettings = Data.Section and Data.Section.IsSettings","","            function Colorpicker:SetOpen(Bool)","                if Debounce then ","                    return ","                end","","                Colorpicker.IsOpen = Bool","","                Debounce = true ","                ","                if Colorpicker.IsOpen then ","                    ColorpickerWindow.Position = Library:PopupPosition(ColorpickerButton, ColorpickerWindow, 0)","","                    ColorpickerWindow.Visible = true","                    Items[\"ColorpickerWindow\"]:Tween({","                        Position = Library:PopupPosition(ColorpickerButton, ColorpickerWindow, 10)","                    })","","                    Items[\"ColorpickerWindow\"]:FadeDescendants(true, function()","                        Debounce = false","                    end)","","                    for Index, Value in Library.OpenFrames do","                        if Value ~= IsSettings then","                            Value:SetOpen(false)","                        end","                    end","","                    Library.OpenFrames[Colorpicker] = Colorpicker ","                else","                    Items[\"ColorpickerWindow\"]:Tween({","                        Position = Library:PopupPosition(ColorpickerButton, ColorpickerWindow, -10)","                    })","","                    Items[\"ColorpickerWindow\"]:FadeDescendants(false, function()","                        Debounce = false","                    end)","","                    if Library.OpenFrames[Colorpicker] then ","                        Library.OpenFrames[Colorpicker] = nil","                    end","                end","","                local Descendants = ColorpickerWindow:GetDescendants()","                table.insert(Descendants, ColorpickerWindow)","","                for Index, Value in Descendants do ","                    if Value.ClassName:find(\"UI\") then","                        continue","                    end","","                    if IsSettings then","                        Value.ZIndex = Colorpicker.IsOpen and Library.ZIndexOrder.ColorpickerWindow + 4 or 1","                    else ","                        Value.ZIndex = Colorpicker.IsOpen and Library.ZIndexOrder.ColorpickerWindow or 1","                    end","                end","            end","","            Items[\"ColorpickerWindow\"]:VisibleCheck()","    ","            local SlidingPalette = false","            local PaletteChanged","            ","            function Colorpicker:SlidePalette(Input)","                if not Input or not SlidingPalette then","                    return","                end","    ","                local ValueX = math.clamp(1 - (Input.Position.X - Items[\"Palette\"].Instance.AbsolutePosition.X) / Items[\"Palette\"].Instance.AbsoluteSize.X, 0, 1)","                local ValueY = math.clamp(1 - (Input.Position.Y - Items[\"Palette\"].Instance.AbsolutePosition.Y) / Items[\"Palette\"].Instance.AbsoluteSize.Y, 0, 1)","    ","                Colorpicker.Saturation = ValueX","                Colorpicker.Value = ValueY","    ","                local SlideX = math.clamp((Input.Position.X - Items[\"Palette\"].Instance.AbsolutePosition.X) / Items[\"Palette\"].Instance.AbsoluteSize.X, 0, 1)","                local SlideY = math.clamp((Input.Position.Y - Items[\"Palette\"].Instance.AbsolutePosition.Y) / Items[\"Palette\"].Instance.AbsoluteSize.Y, 0, 1)","    ","                Items[\"PaletteDragger\"]:Tween({Position = UDim2.new(SlideX, 0, SlideY, 0)}, ColorpickerInfo)","                Colorpicker:Update()","            end","            ","            local SlidingHue = false","            local HueChanged","    ","            function Colorpicker:SlideHue(Input)","                if not Input or not SlidingHue then","                    return","                end","","                local ValueY = math.clamp((Input.Position.Y - Items[\"Hue\"].Instance.AbsolutePosition.Y) / Items[\"Hue\"].Instance.AbsoluteSize.Y, 0, 1)","    ","                Colorpicker.Hue = ValueY","    ","                local SlideY = math.clamp((Input.Position.Y - Items[\"Hue\"].Instance.AbsolutePosition.Y) / Items[\"Hue\"].Instance.AbsoluteSize.Y, 0, 0.99)","    ","                Items[\"HueDragger\"]:Tween({Position = UDim2.new(0, 0, SlideY, 0)}, ColorpickerInfo)","                Colorpicker:Update()","            end","    ","            local SlidingAlpha = false ","            local AlphaChanged","    ","            function Colorpicker:SlideAlpha(Input)","                if not Input or not SlidingAlpha then","                    return","                end","    ","                local ValueY = math.clamp((Input.Position.Y - Items[\"Alpha\"].Instance.AbsolutePosition.Y) / Items[\"Alpha\"].Instance.AbsoluteSize.Y, 0, 1)","    ","                Colorpicker.Alpha = ValueY","    ","                local SlideY = math.clamp((Input.Position.Y - Items[\"Alpha\"].Instance.AbsolutePosition.Y) / Items[\"Alpha\"].Instance.AbsoluteSize.Y, 0, 0.99)","    ","                Items[\"AlphaDragger\"]:Tween({Position = UDim2.new(0, 0, SlideY, 0)}, ColorpickerInfo)","                Colorpicker:Update(true)","            end","    ","            function Colorpicker:Set(Color, Alpha)","                if type(Color) == \"table\" then","                    Color = Color3.fromRGB(Color[1], Color[2], Color[3])","                elseif type(Color) == \"string\" then","                    Color = Color3.fromHex(Color)","                else","                    Color = Color -- Shit","                end ","","                Colorpicker.Hue, Colorpicker.Saturation, Colorpicker.Value = Color:ToHSV()","                Colorpicker.Alpha = Alpha or 0  ","    ","                local PaletteValueX = math.clamp(1 - Colorpicker.Saturation, 0, 0.99)","                local PaletteValueY = math.clamp(1 - Colorpicker.Value, 0, 0.99)","    ","                local AlphaPositionY = math.clamp(Colorpicker.Alpha, 0, 0.99)","                    ","                local HuePositionY = math.clamp(Colorpicker.Hue, 0, 0.99)","    ","                Items[\"PaletteDragger\"]:Tween({Position = UDim2.new(PaletteValueX, 0, PaletteValueY, 0)}, ColorpickerInfo)","                Items[\"HueDragger\"]:Tween({Position = UDim2.new(0, 0, HuePositionY, 0)}, ColorpickerInfo)","                Items[\"AlphaDragger\"]:Tween({Position = UDim2.new(0, 0, AlphaPositionY, 0)}, ColorpickerInfo)","                Colorpicker:Update()","            end","","            Items[\"ColorpickerButton\"]:Connect(\"MouseButton1Down\", function()","                Colorpicker:SetOpen(not Colorpicker.IsOpen)","            end)","    ","            Items[\"Palette\"]:Connect(\"InputBegan\", function(Input)","                if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then","                    SlidingPalette = true ","    ","                    Colorpicker:SlidePalette(Input)","    ","                    if PaletteChanged then","                        return","                    end","    ","                    PaletteChanged = Input.Changed:Connect(function()","                        if Input.UserInputState == Enum.UserInputState.End then","                            SlidingPalette = false","    ","                            PaletteChanged:Disconnect()","                            PaletteChanged = nil","                        end","                    end)","                end","            end)","    ","            Items[\"Hue\"]:Connect(\"InputBegan\", function(Input)","                if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then","                    SlidingHue = true ","    ","                    Colorpicker:SlideHue(Input)","    ","                    if HueChanged then","                        return","                    end","    ","                    HueChanged = Input.Changed:Connect(function()","                        if Input.UserInputState == Enum.UserInputState.End then","                            SlidingHue = false","    ","                            HueChanged:Disconnect()","                            HueChanged = nil","                        end","                    end)","                end","            end)","    ","            Items[\"Alpha\"]:Connect(\"InputBegan\", function(Input)","                if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then","                    SlidingAlpha = true ","    ","                    Colorpicker:SlideAlpha(Input)","    ","                    if AlphaChanged then","                        return","                    end","    ","                    AlphaChanged = Input.Changed:Connect(function()","                        if Input.UserInputState == Enum.UserInputState.End then","                            SlidingAlpha = false","    ","                            AlphaChanged:Disconnect()","                            AlphaChanged = nil","                        end","                    end)","                end","            end)","    ","            Library:Connect(UserInputService.InputChanged, function(Input)","                if Input.UserInputType == Enum