3 = Library.Theme[\"Accent\"],","                    ScaleType = Enum.ScaleType.Slice,","                    ImageTransparency = 0.800000011920929,","                    Size = UDim2.new(1, 25, 1, 25),","                    AnchorPoint = Vector2.new(0.5, 0.5),","                    Image = \"http://www.roblox.com/asset/?id=18245826428\",","                    BackgroundTransparency = 1,","                    Position = UDim2.new(0.5, 0, 0.5, 0),","                    BorderSizePixel = 0,","                    SliceCenter = Rect.new(Vector2.new(21, 21), Vector2.new(79, 79))","                }):AddToTheme({ImageColor3 = 'Accent'})","                ","                Items[\"Inline\"] = Library:Create(\"Frame\", {","                    Name = \"\\0\",","                    Parent = Items[\"Watermark\"].Instance,","                    Size = UDim2.new(0, 0, 0, 25),","                    Position = UDim2.new(0, 0, 0, 6),","                    BorderSizePixel = 0,","                    AutomaticSize = Enum.AutomaticSize.X,","                    BackgroundColor3 = Library.Theme[\"Inline\"]","                }):AddToTheme({BackgroundColor3 = 'Inline'})","                ","                Library:Create(\"UIStroke\", {","                    Name = \"\\0\",","                    Parent = Items[\"Inline\"].Instance,","                    ApplyStrokeMode = Enum.ApplyStrokeMode.Border,","                    LineJoinMode = Enum.LineJoinMode.Miter,","                    Color = Library.Theme[\"Outline\"]","                }):AddToTheme({Color = 'Outline'})","                ","                Library:Create(\"UIStroke\", {","                    Name = \"\\0\",","                    Parent = Items[\"Inline\"].Instance,","                    ApplyStrokeMode = Enum.ApplyStrokeMode.Border,","                    LineJoinMode = Enum.LineJoinMode.Miter,","                    Color = Library.Theme[\"Border\"],","                    BorderOffset = UDim.new(0, 1)","                }):AddToTheme({Color = 'Border'})","                ","                Items[\"Holder\"] = Library:Create(\"Frame\", {","                    Name = \"\\0\",","                    Parent = Items[\"Inline\"].Instance,","                    BackgroundTransparency = 1,","                    Size = UDim2.new(0, 0, 1, 0),","                    BorderSizePixel = 0,","                    AutomaticSize = Enum.AutomaticSize.X","                })","                ","                Library:Create(\"UIListLayout\", {","                    Name = \"\\0\",","                    Parent = Items[\"Holder\"].Instance,","                    VerticalAlignment = Enum.VerticalAlignment.Center,","                    FillDirection = Enum.FillDirection.Horizontal,","                    Padding = UDim.new(0, 6),","                    SortOrder = Enum.SortOrder.LayoutOrder","                })","                ","                Library:Create(\"UIPadding\", {","                    Name = \"\\0\",","                    Parent = Items[\"Holder\"].Instance,","                    PaddingRight = UDim.new(0, 8),","                    PaddingLeft = UDim.new(0, 8)","                })","                ","                Items[\"Title\"] = Library:Create(\"TextLabel\", {","                    Name = \"\\0\",","                    FontFace = Library.Font,","                    TextSize = Library.FontSize,","                    Parent = Items[\"Holder\"].Instance,","                    TextColor3 = Library.Theme[\"Accent\"],","                    Text = Watermark.Name,","                    BackgroundTransparency = 1,","                    BorderSizePixel = 0,","                    AutomaticSize = Enum.AutomaticSize.XY","                }):AddToTheme({TextColor3 = 'Accent'})","                ","                Library:Create(\"UIPadding\", {","                    Name = \"\\0\",","                    Parent = Items[\"Title\"].Instance,","                    PaddingBottom = UDim.new(0, 2)","                })","","                Watermark.Items = Items ","            end","","            function Watermark:SetVisibility(Bool)","                Items[\"Watermark\"].Instance.Visible = Bool","            end","","            function Watermark:SetText(Text)","                Items[\"Title\"].Instance.Text = tostring(Text)","            end","            ","            function Watermark:Add(Text)","                Library:Create(\"Frame\", {","                    Name = \"\\0\",","                    Parent = Items[\"Holder\"].Instance,","                    Size = UDim2.new(0, 1, 1, -10),","                    BorderSizePixel = 0,","                    BackgroundColor3 = Library.Theme[\"Outline\"]","                }):AddToTheme({BackgroundColor3 = 'Outline'})","                ","                local NewItem = Library:Create(\"TextLabel\", {","                    Name = \"\\0\",","                    FontFace = Library.Font,","                    TextSize = Library.FontSize,","                    Parent = Items[\"Holder\"].Instance,","                    TextColor3 = Library.Theme[\"Text\"],","                    Text = Text,","                    BackgroundTransparency = 1,","                    BorderSizePixel = 0,","                    AutomaticSize = Enum.AutomaticSize.XY","                }):AddToTheme({TextColor3 = 'Text'})","","                function NewItem:SetText(Text)","                    NewItem.Instance.Text = tostring(Text)","                end","","                function NewItem:SetVisibility(Bool)","                    NewItem.Instance.Visible = Bool","                end","","                return NewItem","            end","","            Self.Watermark = Watermark","            return setmetatable(Watermark, Library)","        end","","        local KeybindTweenInfo = TweenInfo.new(0.55, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out) -- this is only for the keybind list and should not be used anywhere else","        ","        Library.KeybindList = function(Self)","            local KeybindList = {","                Items = {},","                Keys = {}","            }","        ","            local Items = {} do","                Items[\"KeybindList\"] = Library:Create(\"Frame\", {","                    Name = \"\\0\", ","                    Parent = Library.Holder.Instance, ","                    AnchorPoint = Vector2.new(0, 0.5), ","                    Position = UDim2.new(0, 10, 0.5, 0), ","                    Size = UDim2.new(0, 34, 0, 53), ","                    ClipsDescendants = true, ","                    BorderSizePixel = 0, ","                    BackgroundColor3 = Library.Theme[\"Background\"]","                }):AddToTheme({BackgroundColor3 = \"Background\"})","","                Items[\"KeybindList\"]:MakeDraggable()","        ","                Library:Create(\"UIStroke\", {","                    Parent = Items[\"KeybindList\"].Instance, ","                    ApplyStrokeMode = Enum.ApplyStrokeMode.Border, ","                    LineJoinMode = Enum.LineJoinMode.Miter, ","                    Color = Library.Theme[\"Border\"], ","                    BorderOffset = UDim.new(0, 1)","                }):AddToTheme({Color = \"Border\"})","","                Library:Create(\"UIStroke\", {","                    Parent = Items[\"KeybindList\"].Instance, ","                    ApplyStrokeMode = Enum.ApplyStrokeMode.Border, ","                    LineJoinMode = Enum.LineJoinMode.Miter, ","                    Color = Library.Theme[\"Outline\"]","                }):AddToTheme({Color = \"Outline\"})","        ","                Library:Create(\"UIPadding\", {","                    Parent = Items[\"KeybindList\"].Instance, ","                    PaddingTop = UDim.new(0, 10), ","                    PaddingBottom = UDim.new(0, 12), ","                    PaddingRight = UDim.new(0, 10), ","                    PaddingLeft = UDim.new(0, 10)","                })","        ","                Items[\"Liner\"] = Library:Create(\"Frame\", {","                    Parent = Items[\"KeybindList\"].Instance, ","                    AnchorPoint = Vector2.new(1, 0), ","                    Position = UDim2.new(1, 1, 0, 0), ","                    Size = UDim2.new(1, 2, 0, 2), ","                    BorderSizePixel = 0, ","                    BackgroundColor3 = Library.Theme[\"Accent\"]","                }):AddToTheme({BackgroundColor3 = \"Accent\"})","        ","                Items[\"Glow\"] = Library:Create(\"ImageLabel\", {","                    Parent = Items[\"Liner\"].Instance, ","                    ImageColor3 = Library.Theme[\"Accent\"], ","                    ScaleType = Enum.ScaleType.Slice, ","                    ImageTransparency = 0.8, ","                    Size = UDim2.new(1, 25, 1, 25), ","                    AnchorPoint = Vector2.new(0.5, 0.5), ","                    Image = \"http://www.roblox.com/asset/?id=18245826428\", ","                    BackgroundTransparency = 1, ","                    Position = UDim2.new(0.5, 0, 0.5, 0), ","                    BorderSizePixel = 0, ","                    SliceCenter = Rect.new(Vector2.new(21, 21), Vector2.new(79, 79))","                }):AddToTheme({ImageColor3 = \"Accent\"})","        ","                Items[\"Inline\"] = Library:Create(\"Frame\", {","                    Parent = Items[\"KeybindList\"].Instance, ","                    Size = UDim2.new(0, 8, 0, 25), ","                    Position = UDim2.new(0, 0, 0, 6), ","                    ClipsDescendants = true,","                    BorderSizePixel = 0, ","                    BackgroundColor3 = Library.Theme[\"Inline\"]","                }):AddToTheme({BackgroundColor3 = \"Inline\"})","        ","                Library:Create(\"UIStroke\", {","                    Parent = Items[\"Inline\"].Instance,","                    ApplyStrokeMode = Enum.ApplyStrokeMode.Border, ","                    LineJoinMode = Enum.LineJoinMode.Miter, ","                    Color = Library.Theme[\"Outline\"]","                }):AddToTheme({Color = \"Outline\"})","","                Library:Create(\"UIStroke\", {","                    Parent = Items[\"Inline\"].Instance, ","                    ApplyStrokeMode = Enum.ApplyStrokeMode.Border, ","                    LineJoinMode = Enum.LineJoinMode.Miter, ","                    Color = Library.Theme[\"Border\"], ","                    BorderOffset = UDim.new(0, 1)","                }):AddToTheme({Color = \"Border\"})","        ","                Items[\"Content\"] = Library:Create(\"Frame\", {","                    Parent = Items[\"Inline\"].Instance, ","                    BackgroundTransparency = 1, ","                    Position = UDim2.new(0, 0, 0, 0), ","                    Size = UDim2.new(0, 0, 0, 25), ","                    BorderSizePixel = 0","                })","            end","        ","            Library.KeyList = KeybindList","            Self.KeybindList = KeybindList","        ","            function KeybindList:SetVisibility(Bool)","                Items[\"KeybindList\"].Instance.Visible = Bool","            end","        ","            function KeybindList:UpdateSize()","                local Width = 0","                local Y = 6","                local Count = 0","        ","                for Index, Value in KeybindList.Keys do","                    if Value.Showing then","                        local RowHeight = 14","        ","                        Value.Object.Instance.Visible = true","                        Width = math.max(Width, Value.Object.Instance.TextBounds.X)","        ","                        Value.Object:Tween({Position = UDim2.new(0, 8, 0, Y), Size = UDim2.new(0, Value.Object.Instance.TextBounds.X, 0, RowHeight), TextTransparency = 0}, KeybindTweenInfo)","        ","                        Y += RowHeight + 4","                        Count += 1","                    end","                end","        ","                local TargetHeight = Count \u003e 0 and math.max(25, Y + 5) or 25","        ","                Items[\"Content\"].Instance.Size = UDim2.new(0, Width, 0, TargetHeight)","        ","                Items[\"Inline\"]:Tween({Size = UDim2.new(0, Width + 14, 0, TargetHeight)}, KeybindTweenInfo)","                Items[\"KeybindList\"]:Tween({Size = UDim2.new(0, Width + 34, 0, TargetHeight + 28)}, KeybindTweenInfo)","","                local ActiveKeys = { }","","                for Index, Value in KeybindList.Keys do","                    if Value.Showing then","                        table.insert(ActiveKeys, Value.Object.Instance.Text)","                    end","                end","        ","                if #ActiveKeys == 0 then ","                    Items[\"KeybindList\"].Instance.Visible = false","                else","                    Items[\"KeybindList\"].Instance.Visible = true","                end","            end","        ","            function KeybindList:Add(Name, Mode, Key)","                local NewKeyText = Library:Create(\"TextLabel\", {","                    Parent = Items[\"Content\"].Instance, ","                    FontFace = Library.Font, ","                    TextSize = Library.FontSize, ","                    TextColor3 = Library.Theme[\"Text\"], ","                    Text = Name .. \" - \" .. Mode .. \" [\" .. Key .. \"]\", ","                    BackgroundTransparency = 1, ","                    BorderSizePixel = 0, ","                    Size = UDim2.new(0, 0, 0, 14), ","                    Position = UDim2.new(0, -8, 0, 6), ","                    TextTransparency = 1, ","                    Visible = false, ","                    TextYAlignment = Enum.TextYAlignment.Center, ","                    TextXAlignment = Enum.TextXAlignment.Left","                }):AddToTheme({TextColor3 = \"Text\"})","        ","                local CanShow = true","        ","                local NewKey = {","                    Object = NewKeyText,","                    Showing = false","                }","        ","                table.insert(KeybindList.Keys, NewKey)","        ","                function NewKey:SetVis(Bool)","                    CanShow = Bool","","                    if not Bool then","                        NewKey:SetStatus(false)","                    end","                end","        ","                function NewKey:Set(Name, Mode, Key)","                    NewKey.Object.Instance.Text = Name .. \" - \" .. Mode .. \" [\" .. Key .. \"]\"","","                    KeybindList:UpdateSize()","                end","        ","                function NewKey:SetStatus(Bool)","                    Bool = Bool and CanShow","        ","                    if NewKey.Showing == Bool then","                        return","                    end","        ","                    NewKey.Showing = Bool","        ","                    if Bool then","                        NewKeyText.Instance.Visible = true","                        NewKeyText.Instance.Position = UDim2.new(0, 0, 0, NewKeyText.Instance.Position.Y.Offset)","                        NewKeyText.Instance.TextTransparency = 1","        ","                        KeybindList:UpdateSize()","                    else","                        NewKeyText:Tween({Position = UDim2.new(0, 0, 0, NewKeyText.Instance.Position.Y.Offset), TextTransparency = 1}, KeybindTweenInfo)","        ","                        KeybindList:UpdateSize()","        ","                        task.delay(KeybindTweenInfo.Time, function()","                            if not NewKey.Showing then","                                NewKeyText.Instance.Visible = false","                            end","                        end)","                    end","                end","        ","                return NewKey","            end","        ","            KeybindList:UpdateSize()","        ","            return setmetatable(KeybindList, Library)","        end","","        local NotifTweenInfo = TweenInfo.new(Library.NotifAnimation.Time, Enum.EasingStyle[Library.NotifAnimation.Style], Enum.EasingDirection[Library.NotifAnimation.Direction])","","        Library.Notification = function(Self, Name, Duration, Color)","            Duration = Duration or 5","            Color = Color or Library.Theme.Accent","        ","            local Notification = {","                Duration = Duration,","                Removing = false,","                Items = {}","            }","        ","            local Padding = 8","            local Spacing = 8","        ","            local function UpdatePositions()","                local Y = GuiInset + Padding + 5","            ","                for Index, Value in Library.Notifications do","                    local Height = Value.Items[\"Notification\"].Instance.AbsoluteSize.Y","            ","                    Value.Items[\"Notification\"]:Tween({Position = UDim2.new(0, Padding, 0, Y)}, NotifTweenInfo)","            ","                    Y += Height + Spacing","                end","            end","        ","            local Items = {} do","                Items[\"Notification\"] = Library:Create(\"Frame\", {","                    Name = \"\\0\",","                    Parent = Library.NotifHolder.Instance,","                    Size = UDim2.new(0, 0, 0, 25),","                    AnchorPoint = Vector2.new(0, 0),","                    Position = UDim2.new(0, -260, 0, GuiInset + Padding + 5),","                    BorderSizePixel = 0,","                    AutomaticSize = Enum.AutomaticSize.X,","                    BackgroundColor3 = Library.Theme[\"Inline\"]","                }):AddToTheme({BackgroundColor3 = \"Inline\"})","        ","                Library:Create(\"UIStroke\", {","                    Name = \"\\0\", ","                    Parent = ","                    Items[\"Notification\"].Instance, ","                    ApplyStrokeMode = Enum.ApplyStrokeMode.Border, ","                    LineJoinMode = Enum.LineJoinMode.Miter, ","                    Color = Library.Theme[\"Border\"], ","                    BorderOffset = UDim.new(0, 1)","                }):AddToTheme({Color = \"Border\"})","","                Library:Create(\"UIStroke\", {","                    Name = \"\\0\", ","                    Parent = Items[\"Notification\"].Instance, ","                    ApplyStrokeMode = Enum.ApplyStrokeMode.Border, ","                    LineJoinMode = Enum.LineJoinMode.Miter, ","                    Color = Library.Theme[\"Outline\"]","                }):AddToTheme({Color = \"Outline\"})","        ","                Library:Create(\"UIPadding\", {","                    Name = \"\\0\",","                    Parent = Items[\"Notification\"].Instance,","                    PaddingRight = UDim.new(0, 8),","                    PaddingLeft = UDim.new(0, 8)","                })","        ","                Items[\"Text\"] = Library:Create(\"TextLabel\", {","                    Name = \"\\0\",","                    FontFace = Library.Font,","                    TextSize = Library.FontSize,","                    Parent = Items[\"Notification\"].Instance,","                    TextColor3 = Library.Theme[\"Accent\"],","                    Text = Name,","                    AnchorPoint = Vector2.new(0, 0.5),","                    BackgroundTransparency = 1,","                    Position = UDim2.new(0, 3, 0.5, -1),","                    BorderSizePixel = 0,","                    AutomaticSize = Enum.AutomaticSize.XY","                }):AddToTheme({TextColor3 = \"Text\"})","        ","                Items[\"Liner\"] = Library:Create(\"Frame\", {","                    Name = \"\\0\",","                    Parent = Items[\"Notification\"].Instance,","                    Position = UDim2.new(0, -8, 0, 0),","                    Size = UDim2.new(0, 1, 1, 0),","                    BorderSizePixel = 0,","                    BackgroundColor3 = Color","                })","        ","                Items[\"DurationLiner\"] = Library:Create(\"Frame\", {","                    Name = \"\\0\",","                    Parent = Items[\"Notification\"].Instance,","                    Position = UDim2.new(0, -8, 0, 0),","                    Size = UDim2.new(1, 16, 0, 1),","                    BorderSizePixel = 0,","                    BackgroundColor3 = Color","                })","        ","                Notification.Items = Items","            end","        ","            local FadeNotification = function(Transparency) -- cant use fadedescendants because that one saves the transparency and it breaks and looks really gay ","                Items[\"Notification\"]:Tween({BackgroundTransparency = Transparency}, NotifTweenInfo)","        ","                for _, Value in Items[\"Notification\"].Instance:GetDescendants() do","                    if Value:IsA(\"TextLabel\") then","                        Library:Tween({TextTransparency = Transparency}, NotifTweenInfo, Value)","                    elseif Value:IsA(\"Frame\") then","                        Library:Tween({BackgroundTransparency = Transparency}, NotifTweenInfo, Value)","                    elseif Value:IsA(\"UIStroke\") then","                        Library:Tween({Transparency = Transparency}, NotifTweenInfo, Value)","                    end","                end","            end","        ","            table.insert(Library.Notifications, 1, Notification)","        ","            task.wait()","        ","            local Width = Items[\"Notification\"].Instance.AbsoluteSize.X","            local Height = Items[\"Notification\"].Instance.AbsoluteSize.Y","        ","            Items[\"Notification\"].Instance.Size = UDim2.new(0, Width, 0, Height)","            Items[\"Notification\"].Instance.AutomaticSize = Enum.AutomaticSize.None","            Items[\"Notification\"].Instance.BackgroundTransparency = 1","        ","            for Index, Value in Items[\"Notification\"].Instance:GetDescendants() do","                if Value:IsA(\"TextLabel\") then","                    Value.TextTransparency = 1","                elseif Value:IsA(\"Frame\") then","                    Value.BackgroundTransparency = 1","                elseif Value:IsA(\"UIStroke\") then","                    Value.Transparency = 1","                end","            end","        ","            UpdatePositions()","            FadeNotification(0)","        ","            Items[\"DurationLiner\"]:Tween({Size = UDim2.new(0, 0, 0, 1)}, TweenInfo.new(Duration, Enum.EasingStyle.Linear, Enum.EasingDirection.Out))","        ","            task.spawn(function()","                local Tick = tick()","        ","                while tick() - Tick \u003c Duration and not Notification.Removing do","                    task.wait(0.05)","                end","        ","                if Notification.Removing then return end","        ","                Notification.Removing = true","        ","                if not Library then return end ","","                for Index, Value in Library.Notifications do","                    if Value == Notification then","                        table.remove(Library.Notifications, Index)","                        break","                    end","                end","        ","                Items[\"Notification\"]:Tween({Position = UDim2.new(0, -(Width + Padding + 20), 0, Items[\"Notification\"].Instance.Position.Y.Offset)}, NotifTweenInfo)","","                FadeNotification(1)","        ","                task.delay(NotifTweenInfo.Time, function()","                    Items[\"Notification\"].Instance:Destroy()","                    UpdatePositions()","                end)","            end)","        ","            return Notification","        end","        ","        Library.Window = function(Self, Params)","            Params = Params or { }","","            local Window = {","                Name = Params.Name or Params.name or \"Window\",","","                IsOpen = true,","                Pages = { },","                Items = { }","            }","","            local Items = { } do ","                if IsMobile then ","                    Library:Create(\"UIScale\", {","                        Parent = Library.Holder.Instance,","                        Scale = 0.7","                    })","                end","","                Items[\"Outline\"] = Library:Create(\"Frame\", {","                    Name = \"\\0\",","                    Parent = Library.Holder.Instance,","                    AnchorPoint = Vector2.new(0.5, 0.5),","                    Position = UDim2.new(0.5, 0, 0.5, 0),","                    Size = UDim2.new(0, 613, 0, 453),","                    BorderSizePixel = 0,","                    BackgroundColor3 = Library.Theme[\"Border\"]","                }):AddToTheme({BackgroundColor3 = 'Border'})","","                Items[\"Outline\"]:MakeDraggable()","                Items[\"Outline\"]:MakeResizeable(Vector2.new(Items[\"Outline\"].Instance.AbsoluteSize.X, Items[\"Outline\"].Instance.AbsoluteSize.Y))","                ","                Items[\"Outline2\"] = Library:Create(\"Frame\", {","                    Name = \"\\0\",","                    Parent = Items[\"Outline\"].Instance,","                    Position = UDim2.new(0, 1, 0, 1),","                    Size = UDim2.new(1, -2, 1, -2),","                    BorderSizePixel = 0,","                    BackgroundColor3 = Library.Theme[\"Outline\"]","                }):AddToTheme({BackgroundColor3 = 'Outline'})","                ","                Items[\"Background\"] = Library:Create(\"Frame\", {","                    Name = \"\\0\",","                    Parent = Items[\"Outline2\"].Instance,","                    Position = UDim2.new(0, 1, 0, 1),","                    Size = UDim2.new(1, -2, 1, -2),","                    BorderSizePixel = 0,","                    BackgroundColor3 = Library.Theme[\"Background\"]","                }):AddToTheme({BackgroundColor3 = 'Background'})","                ","                --[[","                Items[\"Title\"] = Library:Create(\"TextLabel\", {","                    Name = \"\\0\",","                    FontFace = Library.Font,","                    TextSize = Library.FontSize,","                    TextXAlignment = Enum.TextXAlignment.Left,","                    Parent = Items[\"Background\"].Instance,","                    TextColor3 = Library.Theme[\"Accent\"],","                    Text = Window.Name,","                    Position = UDim2.new(0, 8, 0, 8),","                    BackgroundTransparency = 1,","                    BorderSizePixel = 0,","                    AutomaticSize = Enum.AutomaticSize.XY","                }):AddToTheme({TextColor3 = 'Accent'})","                --]]","                ","                Items[\"Liner\"] = Library:Create(\"Frame\", {","                    Name = \"\\0\",","                    Parent = Items[\"Background\"].Instance,","                    Size = UDim2.new(1, 0, 0, 2),","                    Position = UDim2.new(0, 0, 0, 30),","                    ZIndex = 2,","                    BorderSizePixel = 0,","                    BackgroundColor3 = Library.Theme[\"Accent\"]","                }):AddToTheme({BackgroundColor3 = 'Accent'})","                ","                Items[\"Glow\"] = Library:Create(\"ImageLabel\", {","                    Name = \"\\0\",","                    Parent = Items[\"Liner\"].Instance,","                    ImageColor3 = Library.Theme[\"Accent\"],","                    ScaleType = Enum.ScaleType.Slice,","                    ImageTransparency = 0.800000011920929,","                    Size = UDim2.new(1, 8, 1, 8),","                    AnchorPoint = Vector2.new(0.5, 0.5),","                    Image = \"http://www.roblox.com/asset/?id=18245826428\",","                    BackgroundTransparency = 1,","                    Position = UDim2.new(0.5, 0, 0.5, 0),","                    BorderSizePixel = 0,","                    SliceCenter = Rect.new(Vector2.new(21, 21), Vector2.new(79, 79))","                }):AddToTheme({ImageColor3 = 'Accent'})","                ","                Items[\"Pages\"] = Library:Create(\"Frame\", {","                    Name = \"\\0\",","                    Parent = Items[\"Background\"].Instance,","                    AnchorPoint = Vector2.new(1, 0),","                    BackgroundTransparency = 1,","                    Position = UDim2.new(1, 0, 0, 0),","                    Size = UDim2.new(0, 0, 0, 30),","                    BorderSizePixel = 0,","                    AutomaticSize = Enum.AutomaticSize.X","                })","                ","                Library:Create(\"UIPadding\", {","                    Name = \"\\0\",","                    Parent = Items[\"Pages\"].Instance,","                    PaddingBottom = UDim.new(0, 4),","                    PaddingRight = UDim.new(0, 8),","                    PaddingLeft = UDim.new(0, 8)","                })","                ","                Library:Create(\"UIListLayout\", {","                    Name = \"\\0\",","                    Parent = Items[\"Pages\"].Instance,","                    VerticalAlignment = Enum.VerticalAlignment.Center,","                    FillDirection = Enum.FillDirection.Horizontal,","                    Padding = UDim.new(0, 8),","                    SortOrder = Enum.SortOrder.LayoutOrder","                })","","                Items[\"Content\"] = Library:Create(\"Frame\", {","                    Name = \"\\0\",","                    Parent = Items[\"Background\"].Instance,","                    BackgroundTransparency = 1,","                    Position = UDim2.new(0, 0, 0, 30),","                    ClipsDescendants = true,","                    Size = UDim2.new(1, 0, 1, -30),","                    BorderSizePixel = 0","                })","","                Window.Items = Items","            end","","            local Debounce = false","","            function Window:SetOpen(Bool)","                if Debounce then ","                    return ","                end","","                for Index, Value in Window.Pages do ","                    if Value.Debounce then ","                        return ","                    end","                end","","                Debounce = true ","","                Window.IsOpen = Bool","                Items[\"Outline\"]:FadeDescendants(Bool, function()","                    Debounce = false","                end)","","                for Index, Value in Library.OpenFrames do ","                    Value:SetOpen(false)","                end","            end","","            function Window:Center()","                local AbsPos = Items[\"Outline\"].Instance.AbsolutePosition","                Items[\"Outline\"].Instance.AnchorPoint = Vector2.new(0, 0)","                task.wait()","                Items[\"Outline\"].Instance.Position = UDim2.new(0, AbsPos.X, 0, AbsPos.Y + GuiInset)","            end","","            Library:Connect(UserInputService.InputBegan, function(Input)","                if tostring(Input.KeyCode) == Library.MenuKeybind or tostring(Input.UserInputType) == Library.MenuKeybind then","                    if UserInputService:GetFocusedTextBox() then","                        return","                    end","","                    Window:SetOpen(not Window.IsOpen)","                end","            end)","","            -- the title animation logic below","            local OffsetX = 8","            local OffsetY = 12","            local Width = 7 -- this would be the gap between each letter","","            local WaveHeight = 4","            local WaveSpeed =  2.5","            local WaveSpacing = 0.25","","            local Letters = { } -- try not to make the title too long since every letter is created individually for the animation","","            for Index = 1, #Window.Name do ","                local Letter = Window.Name:sub(Index, Index)","","                local NewLetter = Library:Create(\"TextLabel\",{","                    Name = \"\\0\",","                    Size = UDim2.new(0, Width, 0, 0),","                    Position = UDim2.new(0, OffsetX + ((Index - 1) * Width), 0, OffsetY),","                    BackgroundTransparency = 1,","                    BorderSizePixel = 0,","                    Text = Letter,","                    FontFace = Library.Font,","                    TextSize = Library.FontSize,","                    Parent = Items[\"Background\"].Instance","                }):AddToTheme({TextColor3 = 'Accent'})","","                Letters[Index] = {","                    LetterInstance = NewLetter,","                    X = OffsetX + ((Index - 1) * Width),","                    Y = OffsetY","                }","            end","","            Library:Connect(RunService.RenderStepped, function()","                local Tick = tick()","","                for Index, Value in Letters do ","                    local OffsetY = math.sin((Tick * WaveSpeed) - (Index * WaveSpacing)) * WaveHeight","","                    Value.LetterInstance.Instance.Position = UDim2.new(0, Value.X, 0, Value.Y + OffsetY)","                end","            end)            ","","            Window:Center()","            return setmetatable(Window, Library)","        end","","        local PageInfo = TweenInfo.new(Library.TabAnimation.Time, Enum.EasingStyle[Library.TabAnimation.Style], Enum.EasingDirection[Library.TabAnimation.Direction])","","        Library.Page = function(Self, Params)","            Params = Params or { }","","            local Page = {","                Name = Params.Name or Params.name or \"Page\",","","                Window = Self,","                ColumnsData = { },","                Items = { },","                Active = false,","                Debounce = false","            }","","            local Items = { } do ","          