utomaticSize.Y,","                    ScrollBarThickness = 0,","                    BackgroundTransparency = 1,","                    Size = UDim2.new(0, 100, 0, 100),","                    BorderSizePixel = 0,","                    CanvasSize = UDim2.new(0, 0, 0, 0)","                })","                ","                Library:Create(\"UIListLayout\", {","                    Name = \"\\0\",","                    Parent = Items[\"LeftColumn\"].Instance,","                    Padding = UDim.new(0, 15),","                    SortOrder = Enum.SortOrder.LayoutOrder","                })","                ","                Library:Create(\"UIPadding\", {","                    Name = \"\\0\",","                    Parent = Items[\"LeftColumn\"].Instance,","                    PaddingTop = UDim.new(0, 19),","                    PaddingBottom = UDim.new(0, 15),","                    PaddingRight = UDim.new(0, 2),","                    PaddingLeft = UDim.new(0, 10)","                })                ","","                Items[\"RightColumn\"] = Library:Create(\"ScrollingFrame\", {","                    Name = \"\\0\",","                    Parent = Items[\"Page\"].Instance,","                    ScrollBarImageColor3 = Color3.fromRGB(0, 0, 0),","                    Active = true,","                    AutomaticCanvasSize = Enum.AutomaticSize.Y,","                    ScrollBarThickness = 0,","                    BackgroundTransparency = 1,","                    Size = UDim2.new(0, 100, 0, 100),","                    BorderSizePixel = 0,","                    CanvasSize = UDim2.new(0, 0, 0, 0)","                })","                ","                Library:Create(\"UIListLayout\", {","                    Name = \"\\0\",","                    Parent = Items[\"RightColumn\"].Instance,","                    Padding = UDim.new(0, 15),","                    SortOrder = Enum.SortOrder.LayoutOrder","                })","                ","                Library:Create(\"UIPadding\", {","                    Name = \"\\0\",","                    Parent = Items[\"RightColumn\"].Instance,","                    PaddingTop = UDim.new(0, 19),","                    PaddingBottom = UDim.new(0, 15),","                    PaddingRight = UDim.new(0, 10),","                    PaddingLeft = UDim.new(0, 2)","                })","","                Page.ColumnsData[1] = Items[\"LeftColumn\"]","                Page.ColumnsData[2] = Items[\"RightColumn\"]","","                Page.Items = Items","            end","","            Items[\"Inactive\"]:OnHover(function()","                if Page.Active then return end ","                ","                Items[\"Inactive\"]:Tween({TextColor3 = Library.Theme.Text})","            end, function()","                if Page.Active then return end ","                ","                Items[\"Inactive\"]:Tween({TextColor3 = Library.Theme[\"Inactive Text\"]})","            end)","","            function Page:Turn()","                local Old = Page.Window.Current ","","                if Old == Page then ","                    return ","                end","","                if Page.Debounce then ","                    return","                end","","                if Old and Old.Debounce then ","                    return ","                end","","                Page.Debounce = true ","                ","                if Old then ","                    Old.Items[\"Page\"].Instance.Position = UDim2.new(0, 0, 0, 0)","                    Old.Items[\"Inactive\"]:ChangeItemTheme({TextColor3 = \"Inactive Text\"})","                    Old.Items[\"Inactive\"]:Tween({TextColor3 = Library.Theme[\"Inactive Text\"]})","","                    Old.Items[\"Page\"]:Tween({Position = UDim2.new(-1, 0, 0, 0)}, PageInfo)","","                    Old.Items[\"Page\"]:FadeDescendants(false, function()","                        Old.Items[\"Page\"].Instance.Parent = Library.UnusedHolder.Instance","                    end)","","                    Old.Active = false","                end","","                Items[\"Page\"].Instance.Position = UDim2.new(1, 0, 0, 0)","                ","                Items[\"Page\"].Instance.Parent = Page.Window.Items[\"Content\"].Instance","                Items[\"Page\"].Instance.Visible = true","                Items[\"Page\"]:FadeDescendants(true, function()","                    Page.Debounce = false","                end)","","                Items[\"Inactive\"]:ChangeItemTheme({TextColor3 = \"Accent\"})","                Items[\"Inactive\"]:Tween({TextColor3 = Library.Theme[\"Accent\"]})","","                Items[\"Page\"]:Tween({Position = UDim2.new(0, 0, 0, 0)}, PageInfo)","","                Page.Window.Current = Page","                Page.Active = true","            end","","            Items[\"Inactive\"]:Connect(\"MouseButton1Down\", function()","                Page:Turn()","            end)","","            if #Page.Window.Pages == 0 then ","                Page:Turn()","            end","","            table.insert(Page.Window.Pages, Page)","            return setmetatable(Page, Library)","        end","","        Library.Section = function(Self, Params)","            Params = Params or { } ","","            local Section = {","                Name = Params.Name or Params.name or \"Section\",","                Side = Params.Side or Params.side or 1,","","                Window = Self.Window,","                Page = Self,","                Items = { },","            }","","            local Items = { } do ","                Items[\"Section\"] = Library:Create(\"Frame\", {","                    Name = \"\\0\",","                    Parent = Section.Page.ColumnsData[Section.Side].Instance,","                    Size = UDim2.new(1, 0, 0, 0),","                    BorderSizePixel = 0,","                    AutomaticSize = Enum.AutomaticSize.Y,","                    BackgroundColor3 = Library.Theme[\"Inline\"]","                }):AddToTheme({BackgroundColor3 = 'Inline'})","                ","                Library:Create(\"UIStroke\", {","                    Name = \"\\0\",","                    Parent = Items[\"Section\"].Instance,","                    ApplyStrokeMode = Enum.ApplyStrokeMode.Border,","                    LineJoinMode = Enum.LineJoinMode.Miter,","                    Color = Library.Theme[\"Outline\"]","                }):AddToTheme({Color = 'Outline'})","                ","                Library:Create(\"UIStroke\", {","                    Name = \"\\0\",","                    Parent = Items[\"Section\"].Instance,","                    ApplyStrokeMode = Enum.ApplyStrokeMode.Border,","                    LineJoinMode = Enum.LineJoinMode.Miter,","                    Color = Library.Theme[\"Border\"],","                    BorderOffset = UDim.new(0, 1)","                }):AddToTheme({Color = 'Border'})","                ","                Items[\"Text\"] = Library:Create(\"TextLabel\", {","                    Name = \"\\0\",","                    FontFace = Library.Font,","                    TextSize = Library.FontSize,","                    TextXAlignment = Enum.TextXAlignment.Left,","                    Parent = Items[\"Section\"].Instance,","                    TextColor3 = Library.Theme[\"Text\"],","                    Text = Section.Name,","                    Position = UDim2.new(0, 9, 0, -2),","                    Size = UDim2.new(0, 0, 0, 1),","                    BorderSizePixel = 0,","                    AutomaticSize = Enum.AutomaticSize.X,","                    BackgroundColor3 = Library.Theme[\"Background\"]","                }):AddToTheme({BackgroundColor3 = 'Background'})","                ","                Library:Create(\"UIPadding\", {","                    Name = \"\\0\",","                    Parent = Items[\"Text\"].Instance,","                    PaddingRight = UDim.new(0, 4),","                    PaddingLeft = UDim.new(0, 4)","                })","                ","                Items[\"Content\"] = Library:Create(\"Frame\", {","                    Name = \"\\0\",","                    Parent = Items[\"Section\"].Instance,","                    BackgroundTransparency = 1,","                    Position = UDim2.new(0, 8, 0, 10),","                    Size = UDim2.new(1, -16, 0, 0),","                    BorderSizePixel = 0,","                    AutomaticSize = Enum.AutomaticSize.Y","                })","                ","                Library:Create(\"UIListLayout\", {","                    Name = \"\\0\",","                    Parent = Items[\"Content\"].Instance,","                    Padding = UDim.new(0, 8),","                    SortOrder = Enum.SortOrder.LayoutOrder","                })","","                Library:Create(\"UIPadding\", {","                    Name = \"\\0\",","                    Parent = Items[\"Section\"].Instance,","                    PaddingBottom = UDim.new(0, 8)","                })                ","","                Section.Items = Items","            end ","","            function Section:SetText(Text)","                Items[\"Text\"].Instance.Text = tostring(Text)","            end","","            return setmetatable(Section, Library)","        end","","        Library.Toggle = function(Self, Params)","            Params = Params or { }","","            local Toggle = {","                Name = Params.Name or Params.name or \"Toggle\",","                Flag = Params.Flag or Params.flag or (Params.Name or Params.name),","                Default = Params.Default or Params.default or false,","                Callback = Params.Callback or Params.callback or function() end,","","                Window = Self.Window,","                Page = Self.Page,","                Section = Self,","","                Value = false,","                Items = { }","            }","","            local Parent ","","            if Params.Parent then ","                Parent = Params.Parent","            else","                Parent = Toggle.Section.Items[\"Content\"]","            end","","            local Items = { } do ","                Items[\"Toggle\"] = Library:Create(\"TextButton\", {","                    Name = \"\\0\",","                    FontFace = Library.Font,","                    TextSize = Library.FontSize,","                    Parent = Parent.Instance,","                    TextColor3 = Color3.fromRGB(0, 0, 0),","                    Text = \"\",","                    AutoButtonColor = false,","                    BackgroundTransparency = 1,","                    Size = UDim2.new(1, 0, 0, 12),","                    BorderSizePixel = 0","                })","                ","                Items[\"Outline\"] = Library:Create(\"Frame\", {","                    Name = \"\\0\",","                    Parent = Items[\"Toggle\"].Instance,","                    AnchorPoint = Vector2.new(0, 0.5),","                    Position = UDim2.new(0, 0, 0.5, 0),","                    Size = UDim2.new(0, 9, 0, 9),","                    BorderSizePixel = 0,","                    BackgroundColor3 = Library.Theme[\"Border\"]","                }):AddToTheme({BackgroundColor3 = 'Border'})","                ","                Items[\"Indicator\"] = Library:Create(\"Frame\", {","                    Name = \"\\0\",","                    Parent = Items[\"Outline\"].Instance,","                    Position = UDim2.new(0, 1, 0, 1),","                    Size = UDim2.new(1, -2, 1, -2),","                    BorderSizePixel = 0,","                    BackgroundColor3 = Library.Theme[\"Element 2\"]","                }):AddToTheme({BackgroundColor3 = 'Element 2'})","                ","                Library:Create(\"UIGradient\", {","                    Name = \"\\0\",","                    Parent = Items[\"Indicator\"].Instance,","                    Rotation = 90,","                    Color = ColorSequence.new{","                    ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 255, 255)),","                    ColorSequenceKeypoint.new(1, Color3.fromRGB(163, 163, 163))","                }","                })","                ","                Items[\"Text\"] = Library:Create(\"TextLabel\", {","                    Name = \"\\0\",","                    FontFace = Library.Font,","                    TextSize = Library.FontSize,","                    TextXAlignment = Enum.TextXAlignment.Left,","                    Parent = Items[\"Toggle\"].Instance,","                    TextColor3 = Library.Theme[\"Text\"],","                    Text = Toggle.Name,","                    Position = UDim2.new(0, 18, 0, -1),","                    BackgroundTransparency = 1,","                    BorderSizePixel = 0,","                    AutomaticSize = Enum.AutomaticSize.XY","                }):AddToTheme({TextColor3 = 'Text'})       ","                ","                Items[\"SubElements\"] = Library:Create(\"Frame\", {","                    Name = \"\\0\",","                    Parent = Items[\"Toggle\"].Instance,","                    AnchorPoint = Vector2.new(1, 0),","                    BackgroundTransparency = 1,","                    Position = UDim2.new(1, 0, 0, 0),","                    Size = UDim2.new(0, 0, 1, 0),","                    BorderSizePixel = 0,","                    AutomaticSize = Enum.AutomaticSize.X","                })","                ","                Library:Create(\"UIListLayout\", {","                    Name = \"\\0\",","                    Parent = Items[\"SubElements\"].Instance,","                    VerticalAlignment = Enum.VerticalAlignment.Center,","                    FillDirection = Enum.FillDirection.Horizontal,","                    Padding = UDim.new(0, 8),","                    SortOrder = Enum.SortOrder.LayoutOrder","                })                ","            ","                Toggle.Items = Items","            end","","            Items[\"Toggle\"]:OnHover(function()","       