"            Items[\"RealDropdown\"]:OnHover(function()","                Items[\"RealDropdown\"]:Tween({BackgroundColor3 = Library.Theme[\"Hovered Element\"]})","            end, function()","                Items[\"RealDropdown\"]:Tween({BackgroundColor3 = Library.Theme.Element})","            end)","","            function Dropdown:Set(Value)","                if Dropdown.Multi then ","                    if type(Value) ~= \"table\" then ","                        return","                    end","","                    Dropdown.Value = Value","","                    for Index, Value in Value do","                        local OptionData = Dropdown.Options[Value]","                         ","                        if not OptionData then","                            continue","                        end","","                        OptionData.IsSelected = true ","                        OptionData:ToggleState(\"Active\")","                    end","","                    Flags[Dropdown.Flag] = Value","                    Items[\"Value\"].Instance.Text = table.concat(Value, \", \")","                else","                    if not Dropdown.Options[Value] then","                        return","                    end","","                    local OptionData = Dropdown.Options[Value]","","                    Dropdown.Value = Value","","                    for Index, Value in Dropdown.Options do","                        if Value ~= OptionData then","                            Value.IsSelected = false ","                            Value:ToggleState(\"Inactive\")","                        else","                            Value.IsSelected = true ","                            Value:ToggleState(\"Active\")","                        end","                    end","","                    Flags[Dropdown.Flag] = Value","                    Items[\"Value\"].Instance.Text = Value","                end","","                Library:SafeCall(Dropdown.Callback, Dropdown.Value)","            end","","            function Dropdown:Add(Value)","                local OptionButton = Library:Create(\"TextButton\", {","                    Name = \"\\0\",","                    FontFace = Library.Font,","                    TextSize = Library.FontSize,","                    TextXAlignment = Enum.TextXAlignment.Left,","                    Parent = Items[\"OptionHolder\"].Instance,","                    TextColor3 = Library.Theme[\"Inactive Text\"],","                    Text = Value,","                    AutoButtonColor = false,","                    Size = UDim2.new(1, 0, 0, 0),","                    BackgroundTransparency = 1,","                    BorderSizePixel = 0,","                    AutomaticSize = Enum.AutomaticSize.Y","                }):AddToTheme({TextColor3 = 'Inactive Text'})","","                local OptionData = {","                    Button = OptionButton,","                    Name = Value,","                    IsSelected = false","                }","","                OptionButton:OnHover(function()","                    if OptionData.IsSelected then return end ","","                    OptionButton:Tween({TextColor3 = Library.Theme.Text})","                end, function()","                    if OptionData.IsSelected then return end ","","                    OptionButton:Tween({TextColor3 = Library.Theme[\"Inactive Text\"]})","                end)","                ","                function OptionData:ToggleState(Value)","                    if Value == \"Active\" then","                        OptionButton:ChangeItemTheme({TextColor3 = \"Accent\"})","                        OptionButton:Tween({TextColor3 = Library.Theme.Accent})","                    else","                        OptionButton:ChangeItemTheme({TextColor3 = \"Inactive Text\"})","                        OptionButton:Tween({TextColor3 = Library.Theme[\"Inactive Text\"]})","                    end","                end","","                function OptionData:Set()","                    Library:Thread(function()","                        Items[\"Value\"]:Tween({TextTransparency = 1})","                        task.wait(0.1)","                        Items[\"Value\"]:Tween({TextTransparency = 0})","                    end)","","                    OptionData.IsSelected = not OptionData.IsSelected","","                    if Dropdown.Multi then ","                        local Index = table.find(Dropdown.Value, OptionData.Name)","","                        if Index then ","                            table.remove(Dropdown.Value, Index)","                        else","                            table.insert(Dropdown.Value, OptionData.Name)","                        end","","                        OptionData:ToggleState(Index and \"Inactive\" or \"Active\")","","                        Flags[Dropdown.Flag] = Dropdown.Value","","                        local TextFormat = #Dropdown.Value \u003e 0 and table.concat(Dropdown.Value, \", \") or \"none\"","                        Items[\"Value\"].Instance.Text = TextFormat","                    else","                        if OptionData.IsSelected then ","                            Dropdown.Value = OptionData.Name","                            Flags[Dropdown.Flag] = OptionData.Name","","                            OptionData.IsSelected = true","                            OptionData:ToggleState(\"Active\")","","                            for Index, Value in Dropdown.Options do ","                                if Value ~= OptionData then","                                    Value.IsSelected = false ","                                    Value:ToggleState(\"Inactive\")","                                end","                            end","","                            Items[\"Value\"].Instance.Text = OptionData.Name","                        else","                            Dropdown.Value = nil","                            Flags[Dropdown.Flag] = nil",""