g(readfile(ThemesFolder .. ThemeSelected .. \".json\"))","","                                if Success then ","                                    Library:Notification(\"Loaded theme \"..ThemeSelected .. \" succesfully\", 3, Library.Theme.Accent)","                                else","                                    Library:Notification(\"Failed to load theme \"..ThemeSelected .. \" report this to the devs: \"..Error, 3, Color3.fromRGB(255, 0, 0))","                                end","                            end","                        end","                    })","","                    ThemingSection:Button({","                        Name = \"Delete\",","                        Callback = function()","                            if ThemeSelected then ","                                if not isfile(ThemesFolder .. ThemeSelected .. \".json\") then","                                    Library:Notification(\"Theme does not exist\", 3, Color3.fromRGB(255, 0, 0))","                                    return","                                end","","                                delfile(ThemesFolder .. ThemeSelected .. \".json\")","                                Library:GetThemesList(ThemesDropdown)","                                Library:Notification(\"Deleted theme \"..ThemeSelected, 3, Library.Theme.Accent)","                            end","                        end","                    })","","                    Library:GetThemesList(ThemesDropdown)","                end","                ","                local MenuSection = SettingsPage:Section({Name = \"Menu\", Side = 2}) do","                    MenuSection:Button({Name = \"Exit\", Callback = function()","                        Library:Exit()","                    end})","","                    MenuSection:Label({ Name = \"Menu Keybind\" }):Keybind({","                        Name = \"Menu Keybind\",","                        Flag = \"MenuKeybind\",","                        Default = Library.MenuKeybind,","                        Mode = \"Toggle\",","                        Callback = function(Value)","                            Library.MenuKeybind = Library.Flags[\"MenuKeybind\"].Key","                        end","                    })","","                    if Self.Watermark then","                        MenuSection:Toggle({","                            Name = \"Watermark\",","                            Flag = \"Watermark\",","                            Default = true,","                            Callback = function(Value)","                                Self.Watermark:SetVisibility(Value)","                            end","                        })","                    end","","                    if Self.KeybindList then ","                        MenuSection:Toggle({","                            Name = \"Keybind list\",","                            Flag = \"Keybind list\",","                            Default = true,","                            Callback = function(Value)","                                Self.KeybindList:SetVisibility(Value)","                            end","                        })","                    end","                end","","                local ConfigName ","                local ConfigSelected ","                local ConfigsFolder = Library.Directory .. Library.Folders.Configs .. \"/\"","","                local ConfigsSection = SettingsPage:Section({Name = \"Profiles\", Side = 1}) do","                    local ConfigsList = ConfigsSection:List({","                        Flag = \"Configs\",","                        Items = { },","                        Multi = false,","                        Callback = function(Value)","                            ConfigSelected = Value","                        end","                    })","","                    ConfigsSection:Textbox({","                        Name = \"Config name\",","                        Flag = \"ConfigName\",","                        Placeholder = \"Config name\",","                        Callback = function(Value)","                            ConfigName = Value ","                        end","                    })","","                    ConfigsSection:Button({","                        Name = \"Create\",","                        Callback = function()","                            if ConfigName then ","                                if ConfigName == \"\" then ","                                    return","                                end","","                                if isfile(ConfigsFolder .. ConfigName .. \".json\") then ","                                    Library:Notification(\"Config with the name \"..ConfigName..\" already exists\", 3, Color3.fromRGB(255, 0, 0))","                                    return","                                end","","                                writefile(ConfigsFolder .. ConfigName .. \".json\", Library:GetConfig())","                                Library:GetConfigsList(ConfigsList)","                                Library:Notification(\"Created config \"..ConfigName, 3, Library.Theme.Accent)","                            end","                        end","                    })","","                    ConfigsSection:Button({","                        Name = \"Load\",","                        Callback = function()","                            if ConfigSelected then ","                                if not isfile(ConfigsFolder .. ConfigSelected .. \".json\") then","                                    Library:Notification(\"Config does not exist\", 3, Color3.fromRGB(255, 0, 0))","                                    return","                                end","","                                local Success, Error = Library:LoadConfig(readfile(ConfigsFolder .. ConfigSelected .. \".json\"))","","                                if Success then ","                                    Library:Notification(\"Loaded config \"..ConfigSelected .. \" succesfully\", 3, Library.Theme.Accent)","                                else","                                    Library:Notification(\"Failed to load config \"..ConfigSelected .. \" report this to the devs: \"..Error, 3, Color3.fromRGB(255, 0, 0))","                                end","                            end","                        end","                    })","","                    ConfigsSection:Button({","                        Name = \"Delete\",","                        Callback = function()","                            if ConfigSelected then ","                                if not isfile(ConfigsFolder .. ConfigSelected .. \".json\") then","                                    Library:Notification(\"Config does not exist\", 3, Color3.fromRGB(255, 0, 0))","                                    return","                                end","","                                delfile(ConfigsFolder .. ConfigSelected .. \".json\")","                                Library:GetConfigsList(ConfigsList)","                                Library:Notification(\"Deleted config \"..ConfigSelected, 3, Library.Theme.Accent)","                            end","                        end","                    })","","                    ConfigsSection:Button({","                        Name = \"Overwrite\",","                        Callback = function()","                            if ConfigSelected then ","                                if not isfile(ConfigsFolder .. ConfigSelected .. \".json\") then","                                    Library:Notification(\"Config does not exist\", 3, Color3.fromRGB(255, 0, 0))","                                    return","                                end","","                                writefile(ConfigsFolder .. ConfigSelected .. \".json\", Library:GetConfig())","                                Library:Notification(\"Overwrote config \"..ConfigSelected, 3, Library.Theme.